        enable_preempt();
        do_exit();
        return 1;
    }

    release_resources(victim);

    if (victim->status == TASK_RUNNING) {
        /* it is running on the other hart, and its page table is live there:
         * flag it and let that hart finish the teardown when it reschedules */
        victim->status = TASK_KILLED;
    } else {
        free_process_user_page(victim->pgdir);
        victim->pgdir = (PTE*)PGDIR_PA;
        reclaim_pcb(victim);
    }

    enable_preempt();
    return 1;
}

