    pcb_t *child = NULL;
    for (int i = 0; i < NUM_MAX_TASK; i++) {
        if (pcb[i].pid == pid) {
            child = &pcb[i];
            break;
        }
    }

    if (child == NULL) {
        /* already gone and cleaned up */
        enable_preempt();
        return 0;
    }

    if (child->status == TASK_ZOMBIE || child->status == TASK_EXITED) {
        /* reap it: release the kernel stack and free the pcb slot */
        free_user_page(kva2pa(child->kernel_stack_base - PAGE_SIZE));
        list_del(&child->list);
        child->status = TASK_EXITED;
        child->pid = -1;
        enable_preempt();
        return 1;
    }

    /* still alive: sleep on it and retry the system call when woken up */
    regs->sepc = regs->sepc - 4;
    do_block(&current_running[cpu_id]->list, &child->wait_list);
    scheduler();

    enable_preempt();
    return pid;
}

